/// A parsed syntax tree. Cheap to clone (refcount bump).
#[derive(Clone)]
#[napi(js_name = "Tree")]
pub struct JsTree {
    inner: Arc<tree_sitter_language_pack::Tree>,
}

#[napi]
impl JsTree {
    /// Return the root `Node` of this tree.
    #[napi(js_name = "rootNode")]
    pub fn root_node(&self) -> JsNode {
        JsNode {
            inner: Arc::new(self.inner.root_node()),
        }
    }

    /// Return a `TreeCursor` positioned at the root.
    #[napi]
    pub fn walk(&self) -> JsTreeCursor {
        JsTreeCursor {
            inner: Arc::new(std::sync::Mutex::new(self.inner.walk())),
        }
    }
}

/// A cursor for traversing a `Tree`.
#[derive(Clone)]
#[napi(js_name = "TreeCursor")]
pub struct JsTreeCursor {
    inner: Arc<std::sync::Mutex<tree_sitter_language_pack::TreeCursor>>,
}

#[napi]
impl JsTreeCursor {
    /// Return the `Node` at the cursor's current position.
    #[napi]
    pub fn node(&self) -> JsNode {
        JsNode {
            inner: Arc::new(self.inner.lock().unwrap().node()),
        }
    }

    /// Move the cursor to the first child of the current node.
    /// Returns `true` if a child existed.
    #[napi(js_name = "gotoFirstChild")]
    pub fn goto_first_child(&self) -> bool {
        self.inner.lock().unwrap().goto_first_child()
    }

    /// Move the cursor to the parent of the current node.
    /// Returns `true` if a parent existed.
    #[napi(js_name = "gotoParent")]
    pub fn goto_parent(&self) -> bool {
        self.inner.lock().unwrap().goto_parent()
    }

    /// Move the cursor to the next sibling of the current node.
    /// Returns `true` if a sibling existed.
    #[napi(js_name = "gotoNextSibling")]
    pub fn goto_next_sibling(&self) -> bool {
        self.inner.lock().unwrap().goto_next_sibling()
    }

    /// Return the field name for the current node, if any.
    #[napi(js_name = "fieldName")]
    pub fn field_name(&self) -> Option<String> {
        self.inner.lock().unwrap().field_name()
    }
}

/// The kind of a comment found in source code.
///
/// Distinguishes between single-line comments, block (multi-line) comments,
/// and documentation comments.
#[napi(string_enum, js_name = "CommentKind")]
#[derive(Clone, serde::Serialize, serde::Deserialize)]
pub enum JsCommentKind {
    /// A single-line comment (e.g., `// ...` or `# ...`).
    Line,
    /// A block or multi-line comment using slash-star delimiters.
    Block,
    /// A documentation comment such as `/// ...` or slash-double-star block.
    Doc,
}

#[allow(clippy::derivable_impls)]
impl Default for JsCommentKind {
    fn default() -> Self {
        Self::Line
    }
}

/// The kind of a data node extracted from a data-format file.
