fn __alef_wire_absent_js<T>(value: &Option<Option<T>>) -> bool {
    matches!(value, None | Some(None))
}

fn __alef_wire_retag_js(mut value: serde_json::Value, from: &str, to: &str) -> serde_json::Value {
    if from != to {
        if let Some(object) = value.as_object_mut() {
            if let Some(tag) = object.remove(from) {
                object.insert(to.to_string(), tag);
            }
        }
    }
    value
}

